-- evt:lever
RegisterEvent(68, "Lever", function()
    if not (((IsAtLeast(MapVar(2), 1)) and (IsAtLeast(MapVar(3), 1)) and (IsAtLeast(MapVar(4), 1)) and (IsAtLeast(MapVar(5), 1))) and (not (IsQBitSet(QBit(118144))))) then
        if IsQBitSet(QBit(118144)) then evt.StatusText("The lever is down.") else evt.SimpleMessage("The lever won't budge.\nA voice booms: Ring the four gongs and then pull the lever. Touch any treasure and you'll have to start over!") end
        evt.SetDoorState(11, DoorAction.Close)
        return
    end
    evt.SetDoorState(9, DoorAction.Open)
    evt.SetDoorState(11, DoorAction.Open)
    SetQBit(QBit(118144))
    evt.PlaySoundName("6stone door0101", 0, 9984, -2360)
    evt.StatusText("The lever moves. Somewhere in the wall chains run, and the iron shutter rises.", 6)
end, "Lever")

