-- evt:shrine_ultimate
RegisterEvent(84, "Shrine of Ultimate Evil", function(continueStep)
    if continueStep == 2 then
        evt.DestroyDestructible(5)
        return
    end
    if continueStep ~= nil then
        return
    end
    if not ((not (evt.IsDestructibleDestroyed(5))) and (not (IsQBitSet(QBit(118148))))) then
        evt.StatusText("The shrine lies broken.")
        return
    end
    evt.SetMessage("Shrine of Ultimate Evil. The walls seem to lean on it, and dust runs from the ceiling. Destroy?")
    evt.AskQuestion(84, 1, 0, 2, "Destroy (Yes/No)?", {"Yes", "Y"})
end, "Shrine of Ultimate Evil")

