-- evt:terminal
RegisterEvent(98, "Main Terminal", function(continueStep)
    if continueStep == 2 then
        XeenQuests.hook("q-f2.terminal")
        return
    end
    if continueStep ~= nil then
        XeenQuests.hook("q-f2.terminal_wrong")
        return
    end
    if not (not (IsQBitSet(QBit(118149)))) then
        XeenQuests.hook("q-f2.terminal")
        return
    end
    evt.SetMessage("Main Terminal\nEnter Code")
    evt.AskQuestion(98, 1, 0, 2, "Code?", {"Computer", "\"Computer\""})
end, "Main Terminal")

